sections.body:
保存为 paired-combat.mjs，执行 node paired-combat.mjs，无额外依赖。本例只有 10⁴=10,000 种等概率输入，因此全部枚举，不做随机抽样；每个十进制编号的四位数字对应四次攻击。代码中的上限只是教学合同。

```js
/**
 * @file Compare combat parameters with event-aligned dice tapes.
 * @author liliwei
 * @date 2026-11-28
 * @LastEditors liliwei
 * @LastEditTime 2026-11-28
 */
/**
 * Resolve four attacks against a 20-HP target.
 * @param {{damage:number, hitFaces:number}} weapon Damage and successful faces out of ten.
 * @param {number[]} rolls Four attack rolls, each an integer from 0 through 9.
 * @returns {number} One for a kill within four attacks, otherwise zero.
 */
export function win(weapon, rolls) {
  if (!weapon || !Number.isInteger(weapon.damage) ||
      weapon.damage < 1 || weapon.damage > 20 ||
      !Number.isInteger(weapon.hitFaces) ||
      weapon.hitFaces < 0 || weapon.hitFaces > 10) {
    throw new Error('Invalid weapon');
  }
  if (!Array.isArray(rolls) || rolls.length !== 4 ||
      !Array.from(rolls).every(x => Number.isInteger(x) && x >= 0 && x <= 9)) {
    throw new Error('Invalid attack tape');
  }
  return Number(rolls.reduce((hp, r) =>
    hp - (r < weapon.hitFaces ? weapon.damage : 0), 20) <= 0);
}
/**
 * Enumerate all equally likely four-roll scenarios without sampling.
 * @param {{damage:number, hitFaces:number}} before Baseline parameters.
 * @param {{damage:number, hitFaces:number}} after Candidate parameters.
 * @returns {object} Joint outcome counts and exact win-rate difference.
 */
export function compare(before, after) {
  win(before, [0, 0, 0, 0]); win(after, [0, 0, 0, 0]);
  const out = { total: 10000, both: 0, gained: 0, lost: 0, neither: 0 };
  for (let id = 0; id < out.total; id++) {
    const rolls = [0, 1, 2, 3].map(t =>
      Math.floor(id / (10 ** t)) % 10);
    const a = win(before, rolls), b = win(after, rolls);
    const key = a ? (b ? 'both' : 'lost') : (b ? 'gained' : 'neither');
    out[key]++;
  }
  return { ...out,
    beforeRate: (out.both + out.lost) / out.total,
    afterRate: (out.both + out.gained) / out.total,
    delta: (out.gained - out.lost) / out.total };
}
const before = { damage: 5, hitFaces: 8 };
const after = { damage: 7, hitFaces: 6 };
console.log(JSON.stringify({ case: 'paired', ...compare(before, after) }));
console.log(JSON.stringify({ case: 'unchanged', ...compare(before, before) }));

// Same pre-generated stream; an extra visual draw shifts attack positions.
const stream = [0, 9, 1, 8, 2, 7, 3, 6];
const sequential = stream.slice(0, 4);
const shifted = [0, 2, 4, 6].map(i => stream[i]);
console.log(JSON.stringify({ case: 'shared-stream-drift',
  sequential, shifted, before: win(before, sequential),
  after: win(before, shifted) }));
```

both 是两版都赢，gained 是旧输新赢，lost 是旧赢新输，neither 是两版都输。delta=(gained−lost)/total，单位是胜率差；百分数显示时应称“百分点”。

末尾 stream 是人为写下的固定序列，模拟同一伪随机流中多消耗一次特效随机数。它没有实现种子生成器，也不是模型或真实引擎的回放。
